// /api/attack-monitor/history?mode=real 는 { history: [...], total } 을 반환한다.
// alerts-polling-to-slack.json과 같은 시간창 필터 방식을 쓰되, 여기서는 CRITICAL만이 아니라
// INFO를 제외한 모든 판정(LOW/MEDIUM/HIGH/CRITICAL)을 Slack으로 보낸다 — 실제 위협 알림(CRITICAL만)은
// 이미 별도로 존재하는 alerts-polling-to-slack.json이 담당하므로, 이 워크플로우는 그보다 더 자세한
// '분석 리포트'(이벤트 목록·요약)를 원할 때 쓰는 보조용이다. 필요 없으면 이 워크플로우는 비활성화해도 된다.
const body = $input.first().json;
const history = body.history || [];
const cutoff = Date.now() - 5 * 60 * 1000;
return history
  .filter((h) => h.created_at && new Date(h.created_at).getTime() > cutoff)
  .filter((h) => h.threat_level && h.threat_level !== 'INFO')
  .map((h) => ({ json: h }));

const h = $json;
const events = h.events || [];
const eventLines = events.slice(0, 5).map((e) => `  - [${e.severity}] ${e.category}: ${e.description}`).join('
');
const text = `[${h.threat_level}] 실시간 공격 모니터링 & 대응 센터 (실제 시스템)
${h.summary}

이벤트 ${events.length}건:
${eventLines}

분석 ID: ${h.id}`;
return { json: { text } };
